/**
 * CommandResponse
 */
export type CommandResponse = {
  /**
   * Send it as after in the next request.
   */
  next?: string;
  /**
   * Goes up when the page changes or the browser restarts.
   */
  epoch: number;
  /**
   * Whether another client changed the session since after.
   */
  epochChanged?: boolean;
  /**
   * The tab the execution used.
   */
  page: {
    tab: string;
    url: string;
    title: string;
  } | null;
  execution: {
    id: string;
    state: "queued" | "running" | "completed" | "failed" | "cancelled" | "timeout" | "expired";
    /**
     * What happened to the page: nothing, a change, or a possible change.
     */
    effect: "none" | "applied" | "unknown";
    replayed: boolean;
    /**
     * Commands started.
     */
    ran: number;
    error?: {
      /**
       * Error code, such as stale_ref or not_actionable.
       */
      code: string;
      message: string;
      /**
       * More detail, such as covered or detached.
       */
      reason?: string;
    };
  };
  results: Array<{
    ok: boolean;
    /**
     * What happened to the page: nothing, a change, or a possible change.
     */
    effect: "none" | "applied" | "unknown";
    error?: {
      /**
       * Error code, such as stale_ref or not_actionable.
       */
      code: string;
      message: string;
      /**
       * More detail, such as covered or detached.
       */
      reason?: string;
    };
    [key: string]: unknown;
  }>;
  observe?: {
    snapshotId?: string;
    snapshot?: string;
    base?: string;
    diff?: string;
    additions?: number;
    removals?: number;
    full?: boolean;
    error?: {
      /**
       * Error code, such as stale_ref or not_actionable.
       */
      code: string;
      message: string;
      /**
       * More detail, such as covered or detached.
       */
      reason?: string;
    };
  };
  /**
   * A dialog that is open on the tab and waits for an answer.
   */
  dialog?: {
    id: string;
    tab: string;
    type: "alert" | "confirm" | "prompt" | "beforeunload";
    message: string;
    defaultPrompt?: string;
    accepted?: boolean;
    text?: string;
    by?: "command" | "client" | "closed";
  };
  events?: {
    cursor: string;
    items: Array<{
      id: string;
      type: string;
      tab: string;
      at: string;
      [key: string]: unknown;
    }>;
    more?: boolean;
    truncated?: boolean;
  };
  bodyExpired?: boolean;
};

/**
 * CommandDialogResponse
 *
 * Response to the dialog command.
 */
export type CommandDialogResponse = {
  /**
   * The dialog that the dialog command answered.
   */
  answered: {
    id: string;
    tab: string;
    type: "alert" | "confirm" | "prompt" | "beforeunload";
    message: string;
    defaultPrompt?: string;
    accepted?: boolean;
    text?: string;
    by?: "command" | "client" | "closed";
  };
  epoch: number;
  events?: {
    cursor: string;
    items: Array<{
      id: string;
      type: string;
      tab: string;
      at: string;
      [key: string]: unknown;
    }>;
    more?: boolean;
    truncated?: boolean;
  };
};

